const status = document.querySelector('#status');
async function request(path, options = {}) {
  const response = await fetch(path, { ...options, headers: { 'Content-Type': 'application/json' } });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error);
  return data;
}
async function load() {
  const notes = await request('/api/notes');
  const list = document.querySelector('#notes');
  list.replaceChildren();
  for (const record of notes) {
    const item = document.createElement('li');
    const label = document.createElement('label');
    label.textContent = 'Working note'; label.htmlFor = record.id;
    const input = document.createElement('textarea');
    input.id = record.id; input.maxLength = 1000; input.value = record.text;
    const save = document.createElement('button'); save.textContent = 'Save note';
    save.addEventListener('click', async () => {
      save.disabled = true; status.textContent = 'Saving…';
      try { await request(`/api/notes/${record.id}`, { method: 'PATCH', body: JSON.stringify({ text: input.value }) }); status.textContent = 'Note saved.'; }
      catch (error) { status.textContent = error.message; }
      finally { save.disabled = false; }
    });
    item.append(label, input, save); list.append(item);
  }
}
document.querySelector('#login').addEventListener('submit', async event => {
  event.preventDefault();
  try {
    await request('/api/login', { method: 'POST', body: JSON.stringify({ username: document.querySelector('#username').value, password: document.querySelector('#password').value }) });
    document.querySelector('#password').value = '';
    await load(); document.querySelector('#login').hidden = true; document.querySelector('#workspace').hidden = false; status.textContent = 'Your notes are ready.';
  } catch (error) { status.textContent = error.message; }
});
document.querySelector('#logout').addEventListener('click', async () => {
  try { await request('/api/logout', { method: 'POST', body: '{}' }); document.querySelector('#workspace').hidden = true; document.querySelector('#notes').replaceChildren(); document.querySelector('#login').hidden = false; status.textContent = 'Signed out.'; }
  catch (error) { status.textContent = error.message; }
});

:root { color-scheme: light; --ink: #182c2b; --muted: #465b58; --paper: #f3f5f2; --panel: #fff; --accent: #176454; --line: #b6c5bd; }
* { box-sizing: border-box; }
body { margin: 0; color: var(--ink); background: var(--paper); font: 1rem/1.5 system-ui, sans-serif; }
main { max-width: 48rem; margin: 0 auto; padding: 2rem 1rem; }
header { margin-bottom: 2rem; }
h1 { font-size: 2rem; margin: .25rem 0; }
h2 { font-size: 1.125rem; margin-top: 0; }
p { margin: .5rem 0; }
.eyebrow { color: var(--accent); font-size: .75rem; font-weight: 700; letter-spacing: .125rem; }
section { background: var(--panel); border: 1px solid var(--line); padding: 1.25rem; border-radius: .5rem; }
label { display: block; font-weight: 600; }
.row { display: flex; gap: .75rem; align-items: center; }
input:not([type="checkbox"]), textarea { width: 100%; padding: .625rem; color: var(--ink); background: var(--panel); border: 1px solid var(--muted); border-radius: .25rem; font: inherit; }
input[type="checkbox"] { width: 1.25rem; height: 1.25rem; margin: .75rem .5rem .75rem 0; }
button { background: var(--accent); color: white; border: 1px solid var(--accent); padding: .625rem 1rem; border-radius: .25rem; font: inherit; cursor: pointer; white-space: nowrap; }
button:disabled { cursor: wait; opacity: .7; }
:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
#feedback { min-height: 1.5rem; margin: 1rem 0; }
#tasks { padding: 0; list-style: none; }
#tasks li { border-top: 1px solid var(--line); padding: 1rem 0; }
h3 { margin: 0 0 .75rem; font-size: 1.125rem; overflow-wrap: anywhere; }
textarea { display: block; min-height: 5rem; resize: vertical; }
.check { display: flex; align-items: center; }
footer { color: var(--muted); font-size: .875rem; padding-top: 1rem; }
@media (max-width: 32rem) { .row { flex-direction: column; align-items: stretch; } main { padding-top: 1rem; } }
